/**
 * Emoji dataset + search.
 *
 * emoji-data.json is generated by tools/make_emoji_data.py from the locally
 * installed IBus dictionaries (ibus-data: emoji-test order and groups, CLDR
 * annotations in English and Chinese). Each record:
 *   e  emoji (fully qualified)      n  English CLDR name
 *   k  English keywords             z  Chinese name + keywords (optional)
 *   t  5 skin-tone variants, light .. dark (optional)
 */

import Gio from 'gi://Gio';

const decoder = new TextDecoder();

function normalize(s) {
    return s.toLowerCase().normalize('NFKC').trim();
}

const CJK = /[㐀-鿿豈-﫿]/;

export class EmojiData {
    constructor(path) {
        const [, bytes] = Gio.File.new_for_path(path).load_contents(null);
        const json = JSON.parse(decoder.decode(bytes));

        this.categories = json.categories;
        this.all = [];
        this._byText = new Map();
        let index = 0;
        for (const cat of this.categories) {
            for (const rec of cat.emoji) {
                rec.index = index++;
                rec.category = cat.id;
                rec.nameWords = normalize(rec.n).split(/[\s:,.!’'“”()-]+/).filter(w => w);
                rec.keywords = (rec.k ?? []).map(normalize);
                rec.zh = rec.z ?? [];
                this.all.push(rec);
                this._byText.set(rec.e.replaceAll('️', ''), rec);
                for (const v of rec.t ?? [])
                    this._byText.set(v.replaceAll('️', ''), rec);
            }
        }
    }

    /** Record for an emoji string (base or skin-tone variant), or null. */
    lookup(text) {
        return this._byText.get(text.replaceAll('️', '')) ?? null;
    }

    /**
     * Records matching every whitespace-separated term of the query, best
     * first: whole name, name prefix, name word prefix, keyword, keyword
     * prefix, substring. Chinese terms match the zh name/keywords by substring.
     */
    search(query, limit = 270) {
        const q = normalize(query);
        if (!q)
            return [];
        const terms = q.split(/\s+/).filter(t => t);
        const scored = [];
        for (const rec of this.all) {
            let total = 0;
            let ok = true;
            for (const term of terms) {
                const s = this._scoreTerm(rec, term);
                if (s < 0) {
                    ok = false;
                    break;
                }
                total += s;
            }
            if (!ok)
                continue;
            const name = normalize(rec.n);
            if (name === q)
                total -= 20;
            else if (name.startsWith(q))
                total -= 10;
            scored.push([total, rec.index, rec]);
        }
        scored.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
        return scored.slice(0, limit).map(s => s[2]);
    }

    _scoreTerm(rec, term) {
        if (CJK.test(term)) {
            let best = -1;
            for (const z of rec.zh) {
                if (z === term)
                    return 0;
                if (z.startsWith(term))
                    best = best < 0 ? 2 : Math.min(best, 2);
                else if (z.includes(term))
                    best = best < 0 ? 4 : Math.min(best, 4);
            }
            return best;
        }
        if (rec.nameWords.includes(term))
            return 0;
        if (rec.nameWords.some(w => w.startsWith(term)))
            return 1;
        if (rec.keywords.includes(term))
            return 2;
        if (rec.keywords.some(k => k.startsWith(term) || k.split(' ').some(w => w.startsWith(term))))
            return 3;
        if (term.length >= 3 && normalize(rec.n).includes(term))
            return 5;
        return -1;
    }
}
